// src/App.js
import { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate, Link } from "react-router-dom";
import axios from "axios";

import AdminPanel from "./components/AdminPanel";
import AuthPage from "./components/Authpage";
import AdminAnonymousResults from "./components/AdminAnonymousResults";
import UserDashboard from "./components/UserDashboard";
import VotingPage from "./components/VotingPage";
import CandidatesPage from "./components/CandidatesPage";
import MyVotesPage from "./components/MyVotesPage";

const API_URL = "http://localhost:5000";

function App() {
  // ================= STATE =================
  const [candidates, setCandidates] = useState([]);
  const [showAnonymous, setShowAnonymous] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");
  const [hasVoted, setHasVoted] = useState(false); // track if user has voted

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    partylist: "",
    yearLevel: "",
    block: "",
    description: "",
    image: null,
  });

  const [selectedVotes, setSelectedVotes] = useState({});

  // ================= THEME =================
  const theme = {
    background: "#f1f5f9",
    navbar: "#ffffff",
    card: "#ffffff",
    text: "#0f172a",
    button: "#6366f1",
  };

  // ================= FETCH CANDIDATES =================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
    const interval = setInterval(fetchCandidates, 3000);
    return () => clearInterval(interval);
  }, []);

  // ================= FETCH USER VOTES =================
  useEffect(() => {
    const fetchMyVotes = async () => {
      if (!auth.token) return;

      try {
        const res = await axios.get(`${API_URL}/api/vote/my`, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });

        setHasVoted(res.data.length > 0); // true if user has voted
      } catch (err) {
        console.error("Failed to fetch your votes:", err);
      }
    };

    fetchMyVotes();
  }, [auth.token]);

  // ================= AUTH =================
  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  if (!auth.token) return <AuthPage setAuth={setAuth} />;

  // ================= SAVE CANDIDATE =================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      Object.keys(candidateForm).forEach((key) => {
        if (candidateForm[key]) formData.append(key, candidateForm[key]);
      });

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated successfully.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added successfully.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        partylist: "",
        yearLevel: "",
        block: "",
        image: null,
      });

      setEditId(null);
      fetchCandidates();
      setTimeout(() => setMessage(""), 3000);
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      setMessage("Candidate deleted.");
      fetchCandidates();
      setTimeout(() => setMessage(""), 3000);
    } catch {
      setMessage("Delete failed.");
    }
  };

  // ================= USER VOTE SUBMIT =================
  const handleVoteSubmit = async () => {
    const candidateIds = Object.values(selectedVotes);

    if (candidateIds.length === 0) {
      alert("Please select at least one candidate before voting.");
      return;
    }

    try {
      await axios.post(
        `${API_URL}/api/vote/batch`,
        { candidateIds },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );

      setSelectedVotes({});
      fetchCandidates();
      setHasVoted(true); // mark user as having voted
      alert("Your vote has been successfully submitted!");
    } catch (err) {
      console.error("Vote submission failed:", err.response || err);
      alert("Vote submission failed!");
    }
  };

  const totalVotes = candidates.reduce((sum, c) => sum + (c.votes || 0), 0);

  // ================= UI =================
  return (
    <Router>
      <div style={{ minHeight: "100vh", backgroundColor: theme.background, color: theme.text }}>
        {/* NAVBAR */}
        <div
          style={{
            position: "sticky",
            top: 0,
            zIndex: 1000,
            backgroundColor: theme.navbar,
            padding: "18px 40px",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            boxShadow: "0 2px 10px rgba(0,0,0,0.08)",
          }}
        >
          <div>
            <h1 style={{ margin: 0, fontSize: 22 }}>SorSU Online Voting</h1>
            <small style={{ opacity: 0.6 }}>Official Student Election Portal</small>
          </div>

          <div style={{ display: "flex", gap: 12 }}>
            {/* USER NAV */}
            {auth.role === "user" && (
              <>
                <Link to="/candidates" style={modernButton(theme)}>Candidates</Link>
                <Link to="/vote" style={modernButton(theme)}>Vote</Link>
                {hasVoted && <Link to="/my-votes" style={modernButton(theme)}>My Ballot</Link>}
              </>
            )}

            {/* ADMIN NAV */}
            {auth.role === "admin" && (
              <>
                <button
                  onClick={() => setShowAnonymous(!showAnonymous)}
                  style={modernButton(theme)}
                >
                  {showAnonymous ? "Hide Chart" : "Anonymous Chart"}
                </button>

                <button
                  onClick={() => setElectionClosed(!electionClosed)}
                  style={{
                    ...modernButton(theme),
                    backgroundColor: electionClosed ? "#10b981" : "#ef4444",
                  }}
                >
                  {electionClosed ? "Open Election" : "Close Election"}
                </button>
              </>
            )}

            <button
              onClick={handleLogout}
              style={{ ...modernButton(theme), backgroundColor: "#ef4444" }}
            >
              Logout
            </button>
          </div>
        </div>

        {/* CONTENT */}
        <div style={{ maxWidth: "1200px", margin: "40px auto", padding: "0 20px" }}>
          {/* ADMIN VIEW */}
          {auth.role === "admin" && (
            <>
              <h2>Live Vote Monitor</h2>

              {message && (
                <div
                  style={{
                    backgroundColor: "#10b981",
                    color: "#fff",
                    padding: "10px 15px",
                    borderRadius: 8,
                    marginBottom: 20,
                  }}
                >
                  {message}
                </div>
              )}

              {showAnonymous ? (
                <AdminAnonymousResults theme={theme} />
              ) : (
                <>
                  <div
                    style={{
                      backgroundColor: theme.card,
                      padding: 15,
                      borderRadius: 8,
                      marginBottom: 20,
                    }}
                  >
                    <strong>Total Votes:</strong> {totalVotes}
                  </div>

                  <AdminPanel
                    candidateForm={candidateForm}
                    setCandidateForm={setCandidateForm}
                    onSave={handleSaveCandidate}
                    editId={editId}
                    setEditId={setEditId}
                    onDelete={handleDeleteCandidate}
                    candidates={candidates}
                    theme={theme}
                  />
                </>
              )}
            </>
          )}

          {/* USER VIEW */}
          {auth.role === "user" && (
            <Routes>
              <Route
                path="/dashboard"
                element={
                  <UserDashboard
                    candidates={candidates}
                    selectedVotes={selectedVotes}
                    setSelectedVotes={setSelectedVotes}
                    handleVoteSubmit={handleVoteSubmit}
                    electionClosed={electionClosed}
                  />
                }
              />
              <Route
                path="/vote"
                element={<VotingPage auth={auth} electionClosed={electionClosed} />}
              />
              <Route
                path="/candidates"
                element={<CandidatesPage auth={auth} />}
              />
              <Route
                path="/my-votes"
                element={<MyVotesPage auth={auth} />}
              />
              <Route path="*" element={<Navigate to="/dashboard" />} />
            </Routes>
          )}
        </div>
      </div>
    </Router>
  );
}

// BUTTON STYLE
const modernButton = (theme) => ({
  padding: "8px 14px",
  backgroundColor: theme.button,
  color: "#fff",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  fontWeight: "500",
  fontSize: "14px",
  textDecoration: "none",
  transition: "0.2s ease",
});

export default App;
